import type { DockManager } from './DockManager';

export interface Size {
  width: number;
  height: number;
}

export interface Rect {
  x: number;
  y: number;
  width: number;
  height: number;
}

/** Where a dragged panel lands. 'float' = released over nothing dockable. */
export type DropZone = 'center' | 'left' | 'right' | 'top' | 'bottom' | 'float';

interface BaseNode {
  /** Node id — generated by tabs() / split() unless given; pass a stable one
   *  when code targets the node (`dockableIn`, `home`, `openPanel`). */
  id: string;
  /**
   * A locked node is frozen: its panels cannot be dragged out or floated,
   * nothing can be dropped into it, its tabs have no close buttons, and the
   * splitters touching it are inert. Use it for toolbars, status bars, fixed
   * sidebars. Locking is inherited by everything inside.
   */
  locked?: boolean;
  /** Pixel size along the parent split's axis. Beats the content minimum. */
  fixedSize?: number;
}

/** A row/column of child nodes with draggable splitters between them. */
export interface SplitNode extends BaseNode {
  type: 'split';
  /** 'row' = side by side, 'column' = stacked. */
  direction: 'row' | 'column';
  /** The nodes in order (left to right, or top to bottom). */
  children: LayoutNode[];
  /** Weights, parallel to `children`. Any positive scale works; only ratios matter. */
  sizes: number[];
}

/** A leaf: one or more panels sharing a tab strip. */
export interface TabsNode extends BaseNode {
  type: 'tabs';
  /** Panel ids in tab order. */
  panels: string[];
  /** The visible tab (default: the first). */
  activePanel?: string;
  /** Hide the tab strip. Only sensible for a single-panel node (e.g. a toolbar). */
  hideTabs?: boolean;
  /**
   * Collapsed to its tab strip alone: a header in a column, a narrow rail in a
   * row. Its siblings take the space. Panel content is detached, not destroyed —
   * React state and WebGL contexts survive a collapse.
   */
  collapsed?: boolean;
  /** Default true — but a `locked` node only collapses when this is
   *  explicitly true. False hides the chevron AND the size-lock padlock, and
   *  refuses `toggleCollapse`. */
  collapsible?: boolean;
  /**
   * The tab-strip padlock. Locking captures the group's CURRENT size as its
   * minimum — nothing more: it can still grow, but never shrinks below the
   * size it was locked at, so divider drags cascade straight past it to the
   * next sibling. Container resizes still scale the group proportionally,
   * and chevron collapse is unaffected. Declared in a layout, it only shows
   * the padlock ON: the floor is `lockedSize`, which the padlock (and
   * `toggleSizeLock`) capture — give both for a floor from the start.
   */
  sizeLocked?: boolean;
  /**
   * The group's pixel size captured by the padlock at lock time — its
   * minimum (both axes) while `sizeLocked` is on. Folded into measureMin, so
   * it holds through any nesting and through container resizes. Managed by
   * the manager; cleared on unlock.
   */
  lockedSize?: Size;
}

export type LayoutNode = SplitNode | TabsNode;

/** A panel (or a whole sub-layout) lifted out of the dock into a dialog. */
export interface FloatingWindow extends Rect {
  /** Window id (`dockWindow`, `closeWindow`, `minimizeWindow` take it). */
  id: string;
  /** The panel — or a whole sub-layout — the window holds. */
  node: LayoutNode;
  /** Stacking order. The manager bumps this on interaction. */
  z: number;
  /** Collapsed to just the title bar. */
  minimized?: boolean;
}

/** Everything you need to restore a workspace. Plain JSON. */
export interface DockState {
  /** The docked tree. */
  root: LayoutNode;
  /** The floating windows, each with its own tree. */
  windows: FloatingWindow[];
}

export interface PanelContext {
  /** The panel's id. */
  readonly id: string;
  /** The manager the panel lives in. */
  readonly manager: DockManager;
  /** Set the tab title (the definition's `title` until then). */
  setTitle(title: string): void;
  /** Content declares how small it is willing to get — it replaces the
   *  definition's minWidth / minHeight (an omitted axis keeps it). Propagates
   *  up the tree. */
  setMinSize(min: Partial<Size>): void;
  /** Close the panel — a real close (`beforeClose` / `onClose` run). */
  close(): void;
  /** Lift this panel out into a floating dialog. */
  float(rect?: Partial<Rect>): void;
  /** Its tab is the visible one in its group. */
  isActive(): boolean;
  /** It lives in a floating window. */
  isFloating(): boolean;
}

/**
 * Mount panel content into `host`. Return a disposer, called whenever the
 * content is unmounted — a close, but also a layout swap that drops the panel,
 * `remountPanel`, and `unmount()` of the whole dock. Pure DOM by default — see
 * `reactPanel()` for React content.
 */
export type PanelRenderer = (host: HTMLElement, ctx: PanelContext) => undefined | (() => void);

export interface PanelDefinition {
  /** Stable id — what layouts, `openPanel` and saved states name. */
  id: string;
  /** Tab title (`ctx.setTitle` / `usePanelTitle` change it at runtime). */
  title: string;
  /** Minimum content width in px (default 120). `useMinSize` / `ctx.setMinSize` replace it at runtime. */
  minWidth?: number;
  /** Minimum content height in px, excluding the tab strip (default 60). */
  minHeight?: number;
  /** Default true. Locked nodes never show close buttons regardless. */
  closable?: boolean;
  /** Default true. False keeps the panel docked. */
  floatable?: boolean;
  /**
   * Pin the panel to one or more nodes, by id. It can then only ever be dropped
   * into those nodes — no floating, no splitting, no docking elsewhere — which
   * leaves reordering its own tab strip as the only move. Give the node a stable
   * id yourself: `tabs(['a', 'b'], { id: 'top' })`.
   */
  dockableIn?: string | string[];
  /** Soft default node — where the panel reopens when its last location is
   *  unknown. Unlike `dockableIn` this does NOT pin the panel; it can still be
   *  dragged anywhere. Falls through to the first open node if the node is gone. */
  home?: string;
  /** Minimum width of the tab button, px — replaces the dock's `tabMinWidth`. Use it to align a strip of tabs. */
  tabMinWidth?: number;
  /** Called when the panel is CLOSED — the tab ×, `closePanel`, `togglePanel`,
   *  `ctx.close()`, `closeWindow`. NOT called when a layout swap (loadLayout /
   *  resetLayout / solo) unmounts the content, so a runtime panel can clean
   *  itself up on a real close without disappearing every time the layout
   *  changes. */
  onClose?: (panelId: string) => void;
  /** Called before a REAL close (the same routes as `onClose`). Return a
   *  promise to DEFER it: the panel disappears at once — tab gone, content
   *  `display:none` but still mounted, in place — and is detached and disposed
   *  when the promise settles, so content can flush state (an iframe page
   *  saving) before it is unmounted. Return nothing to close at once. Not
   *  consulted on layout swaps, which unmount immediately, nor by
   *  `unregisterPanel`, which closes silently. */
  beforeClose?: (panelId: string) => Promise<void> | undefined;
  /** Mounts the content (see PanelRenderer; `definePanel` builds it for React). */
  render: PanelRenderer;
}

export interface DockManagerOptions {
  /** Every panel the dock can show (more can come later with registerPanel). */
  panels: PanelDefinition[];
  /** Initial tree — adopted and mutated in place (drags write sizes into it),
   *  so build it inside the factory; resetLayout() returns to a copy. */
  layout: LayoutNode;
  /** Floating windows to start with. */
  windows?: FloatingWindow[];
  /** Height of ONE tab row in px (default 22, on every pointer type). A strip
   *  whose tabs wrap keeps each row this tall, and the taller strip is folded
   *  into the group's minimum. */
  headerHeight?: number;
  /** Minimum tab width for every tab, px. A panel's own `tabMinWidth` replaces it. */
  tabMinWidth?: number;
  /** Splitter thickness in px. Default 6. The hit area widens on coarse pointers. */
  splitterSize?: number;
  /** Floating window title bar height in px. Default 26. */
  windowBarHeight?: number;
  /** Size of a window created by dragging a tab out. Default 340×260. */
  defaultWindowSize?: Size;
}
